/* replay: fixed session key/salt; ops are sequences with the stable
 * verdict vocabulary (the AEAD input each side rebuilds is pinned by the
 * ccm group). */
typedef struct {
    const char *name;
    const uint8_t *key;  /* 16 B */
    const uint8_t *salt; /* 5 B */
    const unsigned long long *seqs;
    const char *const *verdicts;
    size_t n;
} dtn_link_replay_vec;

